import base64
import pathlib
import subprocess
import sys
import tempfile

subprocess.run(
    [
        sys.executable,
        "-m",
        "pip",
        "install",
        "-q",
        "qiskit",
        "qiskit-machine-learning",
        "numpy",
    ],
    check=True,
)

SOURCES_B64 = {
  "Day34/create_qnn.py": "",
  "Day34/torch_connector.py": "",
  "Day34/3-9.py": "",
  "Day34/3-10.py": "",
  "Day34/3-8.py": "",
  "Day34/3-7.py": "",
  "Day35/1-1.py": ""
}

EXECUTION_ORDER = [
    "Day34/create_qnn.py",
    "Day34/torch_connector.py",
    "Day34/3-7.py",
    "Day34/3-8.py",
    "Day34/3-9.py",
    "Day34/3-10.py",
    "Day35/1-1.py",
]

with tempfile.TemporaryDirectory(prefix="quantum-ml-day34-day35-") as tmp:
    root = pathlib.Path(tmp)
    for relative_path, payload in SOURCES_B64.items():
        destination = root / relative_path
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(base64.b64decode(payload))

    for relative_path in EXECUTION_ORDER:
        day, name = relative_path.split("/", 1)
        label = f"{day}/{name}"
        print(f"COLAB_SOURCE_START {label}", flush=True)
        subprocess.run([sys.executable, name], cwd=root / day, check=True)
        print(f"COLAB_SOURCE_OK {label}", flush=True)

print("COLAB_DAY34_DAY35_SOURCE_EXECUTION_OK", flush=True)
